#include "Mime2Rdf4C.h"
#include <stdlib.h>
#include <string.h>

//TODO replace accessiri with autogenerated with uuid
const char* default_accessiri = "http://example.com/Mime2Rdf4C/.well-known";

int Mime2Rdf4C_util_use_file_as_base(Mime2Rdf4C_ParserConfig* config, const char* filepath, const char* accessiri, size_t access_depth)
{
	int err;
	const char* relative_filepath;
	char *accesspath, *fileiri, *tmp;
	size_t l_accesspath, l_fileiri;
	if(accessiri == NULL) accessiri = default_accessiri;
	if(config == NULL){
		fprintf(stderr, "Mime2Rdf4C_util_use_file_as_base got "
				"NULL as config\n");
		return 1;
	}
	if(access_depth != 0){
		fprintf(stderr, "ERROR Mime2Rdf4C_util_use_file_as_base "
				"not implemented for access_depth != 0\n");
		return 1;
	}
	relative_filepath = strrchr(filepath, '/');
	l_accesspath = relative_filepath - filepath;
	accesspath = malloc(l_accesspath + 1);
	memcpy(accesspath, filepath, l_accesspath);
	accesspath[l_accesspath] = '\0';

	err = Mime2Rdf4C_enable_LoadDocumentCallback_for_relativefiles(config, 
			accessiri, accesspath);
	free(accesspath);
	if(err != 0){
		fprintf(stderr, "ERROR Mime2Rdf4C_util_use_file_as_base"
				"(Mime2Rdf4C_enable_LoadDocumentCallback_"
				"for_relativefiles)\n");
		return 1;
	}

	l_fileiri = strlen(accessiri) + strlen(relative_filepath);
	fileiri = malloc(l_fileiri + 1);
	strcpy(fileiri, accessiri);
	tmp = fileiri + strlen(fileiri);
	strcpy(tmp, relative_filepath);
	err = Mime2Rdf4C_set_baseiri(config, fileiri);
	free(fileiri);
	if(err != 0){
		fprintf(stderr, "ERROR Mime2Rdf4C_util_use_file_as_base"
				"(Mime2Rdf4C_set_baseiri)\n");
		return 1;
	}
	return 0;
}
